        if (readU64(v)) {
            x = u32(v);
        }
        return *this;
    }
    // 读入 u64；到输入末尾时保持 x 不变
    FastIO &operator>>(u64 &x) {
        readU64(x);
        return *this;
    }
    // 读入 int；到输入末尾时保持 x 不变
    FastIO &operator>>(int &x) {
        i64 v = 0;
        if (readI64(v)) {
            x = int(v);
        }
        return *this;
    }
    // 读入 i64；到输入末尾时保持 x 不变
    FastIO &operator>>(i64 &x) {
        readI64(x);
        return *this;
    }

    // 输出一个字符
    FastIO &operator<<(char x) {
        put(x);
        return *this;
    }
    // 输出 C 风格字符串
    FastIO &operator<<(const char *str) {
        while (*str) {
            put(*str++);
        }
        return *this;
    }
    // 输出 u32
    FastIO &operator<<(u32 x) {
        writeU64(u64(x));
        return *this;
    }
    // 输出 u64
    FastIO &operator<<(u64 x) {
        writeU64(x);
        return *this;
    }
    // 输出 int
    FastIO &operator<<(int x) {
        writeI64(i64(x));
        return *this;
    }
    // 输出 i64
    FastIO &operator<<(i64 x) {
        writeI64(x);
        return *this;
    }
} io;

