struct DSU {
    // f[u] 是并查集父节点，不一定是代表；siz 只有在代表处有效，读 siz[find(u)]
    std::vector<int> f, siz;

    // 空对象使用前先调用 init(n)
    DSU() {}
    DSU(int n) {
        init(n);
    }

    // 重置为 n 个独立集合
    void init(int n) {
        f.resize(n);
        std::iota(f.begin(), f.end(), 0);
        siz.assign(n, 1);
    }

    // 返回 x 所在集合的代表编号
    int find(int x) {
        while (x != f[x]) {
            x = f[x] = f[f[x]];
        }
        return x;
    }

    // 判断是否同组
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    // 合并成功返回 true，原本同组返回 false
    bool merge(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) {
            return false;
        }
        if (siz[x] < siz[y]) {
            std::swap(x, y);
        }
        siz[x] += siz[y];
        f[y] = x;
        return true;
    }

    // 返回所在组的元素数
    int size(int x) {
        return siz[find(x)];
    }
};

class GraphComponentDSU {
    DSU dsu;
    vector<i64> edgeCount;
    vector<bool> loop;

  public:
    explicit GraphComponentDSU(int n) : dsu(n), edgeCount(n), loop(n) {
        assert(n >= 0);
    }

    // 加无向边；合并了不同连通块时返回 true
    bool addEdge(int u, int v) {
        int a = dsu.find(u), b = dsu.find(v);
        i64 count = edgeCount[a] + 1;
        bool self = loop[a] || u == v;
        if (a != b)
            count += edgeCount[b], self = self || loop[b];

        bool merged = dsu.merge(a, b);
        int root = dsu.find(a);
        edgeCount[root] = count;
        loop[root] = self;
        return merged;
    }

    // 返回所在连通块的点数
    int vertices(int u) {
        return dsu.size(u);
    }

    // 返回边数，重边和自环照计
    i64 edges(int u) {
        return edgeCount[dsu.find(u)];
    }

    // 是否有自己连自己的边
    bool hasSelfLoop(int u) {
        return loop[dsu.find(u)];
    }
};

