template <class T, class Op> class ZKWSegmentTree {
    int n = 0, base = 1;
    vector<T> t;
    Op op;

  public:
    // 从数组建立 zkw 树；数组不可为空。
    ZKWSegmentTree(const vector<T> &a, Op operation) : n(a.size()), op(operation) {
        assert(n > 0);
        while (base < n)
            base <<= 1;
        t.resize(base << 1);
        for (int i = 0; i < n; i++)
            t[base + i] = a[i];
        for (int i = base - 1; i; i--)
            t[i] = op(t[i << 1], t[i << 1 | 1]);
    }
    // 把位置 p 赋为 x；0<=p<n。
    void set(int p, const T &x) {
        assert(0 <= p && p < n);
        t[base + p] = x;
        for (int i = (base + p) >> 1; i; i >>= 1)
            t[i] = op(t[i << 1], t[i << 1 | 1]);
    }
    // 返回非空 [l,r) 的有序合并结果。
    T query(int l, int r) const {
        assert(0 <= l && l < r && r <= n);
        l += base;
        r += base;
        bool hasL = false, hasR = false;
        T L{}, R{};
        while (l < r) {
            if (l & 1) {
                L = hasL ? op(L, t[l]) : t[l];
                hasL = true;
                l++;
            }
            if (r & 1) {
                --r;
                R = hasR ? op(t[r], R) : t[r];
                hasR = true;
            }
            l >>= 1;
            r >>= 1;
        }
        return hasL ? (hasR ? op(L, R) : L) : R;
    }
};

