// 返回方阵行列式，按值接收矩阵
template <class T> T det(std::vector<std::vector<T>> a) {
    int n = a.size();
    T ans = 1;
    for (int i = 0; i < n; i++) {
        int p = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j][i] != 0) {
                p = j;
                break;
            }
        }
        if (a[p][i] == 0) {
            return 0;
        }
        if (p != i) {
            std::swap(a[i], a[p]);
            ans = -ans;
        }
        ans *= a[i][i];
        T inv = a[i][i].inv();
        for (int j = i + 1; j < n; j++) {
            T t = a[j][i] * inv;
            for (int k = i; k < n; k++) {
                a[j][k] -= t * a[i][k];
            }
        }
    }
    return ans;
}

// 返回无向图生成树数量模 P
Z countSpanningTree(int n, const std::vector<std::pair<int, int>> &edges) {
    if (n <= 1) {
        return 1;
    }
    std::vector<std::vector<Z>> lap(n, std::vector<Z>(n));
    for (auto [u, v] : edges) {
        if (u == v) {
            continue;
        }
        lap[u][u] += 1;
        lap[v][v] += 1;
        lap[u][v] -= 1;
        lap[v][u] -= 1;
    }
    std::vector<std::vector<Z>> a(n - 1, std::vector<Z>(n - 1));
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1; j++) {
            a[i][j] = lap[i][j];
        }
    }
    return det(a);
}

