namespace tree_count {
    using V = std::vector<int>;
    constexpr int mod = poly::MOD;
    // 给定无向树邻接表，返回最小叶子顺序的Prüfer码。
    V encode(const std::vector<V> &adj) {
        int n = adj.size();
        assert(n >= 1);
        V d(n);
        int total = 0;
        for (int u = 0; u < n; ++u) {
            d[u] = adj[u].size();
            total += d[u];
            for (int v : adj[u])
                assert(v >= 0 && v < n && v != u);
        }
        assert(total == 2 * (n - 1));
        std::priority_queue<int, V, std::greater<int>> q;
        for (int i = 0; i < n; ++i)
            if (d[i] == 1)
                q.push(i);
        V code;
        for (int i = 0; i < n - 2; ++i) {
            assert(!q.empty());
            int u = q.top();
            q.pop();
            int v = -1;
            for (int x : adj[u])
                if (d[x]) {
                    v = x;
                    break;
                }
            assert(v >= 0);
            code.push_back(v);
            d[u] = 0;
            if (--d[v] == 1)
                q.push(v);
        }
        return code;
    }
    // 解码Prüfer码，返回无向边；n=1时返回空。
    std::vector<std::pair<int, int>> decode(const V &code, int n) {
        assert(n >= 1 && code.size() == std::max(0, n - 2));
        if (n == 1)
            return {};
        V d(n, 1);
        for (int v : code) {
            assert(v >= 0 && v < n);
            ++d[v];
        }
        std::priority_queue<int, V, std::greater<int>> q;
        for (int i = 0; i < n; ++i)
            if (d[i] == 1)
                q.push(i);
        std::vector<std::pair<int, int>> e;
        for (int v : code) {
            int u = q.top();
            q.pop();
            e.emplace_back(u, v);
            --d[u];
            if (--d[v] == 1)
                q.push(v);
        }
        int u = q.top();
        q.pop();
        e.emplace_back(u, q.top());
        return e;
    }
    // 返回指定/自由度数的标号树数；-1自由，无效度数组合返回0。
    int partialDegrees(const V &degrees) {
        int n = degrees.size();
        assert(n >= 1 && n < mod);
        if (n == 1)
            return degrees[0] == -1 || degrees[0] == 0;
        counting::Classic t(n);
        int used = 0, free = 0;
        long long den = 1;
        for (int d : degrees) {
            if (d == -1) {
                ++free;
                continue;
            }
            if (d < 1 || d >= n)
                return 0;
            used += d - 1;
            if (used > n - 2)
                return 0;
            den = den * t.invfact[d - 1] % mod;
        }
        int remain = n - 2 - used;
        return 1LL * t.fact[n - 2] * den % mod * t.invfact[remain] % mod *
               poly::powerMod(free, remain) % mod;
    }
    // 返回连接给定块的方案数；各块内部固定，跨块边的端点任取。
    int joinComponents(const V &sizes) {
        assert(!sizes.empty());
        long long n = 0, prod = 1;
        for (int s : sizes) {
            assert(s > 0);
            n += s;
            prod = prod * (s % mod) % mod;
        }
        if (sizes.size() == 1)
            return 1;
        return prod * poly::powerMod(n % mod, sizes.size() - 2) % mod;
    }
    // 返回无标号有根/无根树数[0,n]，空树项0。
    std::pair<V, V> unlabelled(int n) {
        assert(n >= 0 && n < mod);
        V a(n + 1), b(n + 1), divsum(n + 1), inv(n + 1);
        if (n)
            inv[1] = 1;
        for (int i = 2; i <= n; ++i)
            inv[i] = 1LL * (mod - mod / i) * inv[mod % i] % mod;
        for (int m = 1; m <= n; ++m) {
            long long s = m == 1 ? 1 : 0;
            if (m > 1) {
                s = 0;
                for (int j = 1; j < m; ++j)
                    s = (s + 1LL * divsum[j] * a[m - j]) % mod;
                s = s * inv[m - 1] % mod;
            }
            a[m] = s;
            for (int j = m; j <= n; j += m)
                divsum[j] = (divsum[j] + 1LL * m * a[m]) % mod;
            long long pairs = 0;
            for (int j = 1; j < m; ++j)
                pairs = (pairs + 1LL * a[j] * a[m - j]) % mod;
            b[m] = (a[m] - pairs * ((mod + 1) / 2) % mod +
                    (m % 2 == 0 ? 1LL * a[m / 2] * ((mod + 1) / 2) % mod : 0) + mod) %
                   mod;
        }
        return {a, b};
    }
}

