#endif // XCPC_MODINT
namespace directed_tree {
    namespace detail {
        template <class T> T det(std::vector<std::vector<T>> a) {
            int n = a.size();
            T ans = 1;
            for (int i = 0; i < n; i++) {
                int p = i;
                for (int j = i + 1; j < n; j++) {
                    if (a[j][i] != 0) {
                        p = j;
                        break;
                    }
                }
                if (a[p][i] == 0) {
                    return 0;
                }
                if (p != i) {
                    std::swap(a[i], a[p]);
                    ans = -ans;
                }
                ans *= a[i][i];
                T inv = a[i][i].inv();
                for (int j = i + 1; j < n; j++) {
                    T t = a[j][i] * inv;
                    for (int k = i; k < n; k++) {
                        a[j][k] -= t * a[i][k];
                    }
                }
            }
            return ans;
        }

    }
    // 返回树的边权乘积之和；type=0无向/1外向/2内向，删除root对应行列。
    Z weighted(int n, const std::vector<std::tuple<int, int, Z>> &edges, int root, int type) {
        assert(n >= 1 && root >= 0 && root < n && type >= 0 && type <= 2);
        std::vector<std::vector<Z>> a(n - 1, std::vector<Z>(n - 1));
        auto index = [&](int u) { return u < root ? u : u - 1; };
        auto add = [&](int u, int v, Z w) {
            if (u != root && v != root)
                a[index(u)][index(v)] += w;
        };
        for (auto [u, v, w] : edges) {
            assert(u >= 0 && u < n && v >= 0 && v < n);
            if (u == v)
                continue;
            if (type == 0) {
                add(u, u, w);
                add(v, v, w);
                add(u, v, -w);
                add(v, u, -w);
            } else if (type == 1) {
                add(v, v, w);
                add(u, v, -w);
            } else {
                add(u, u, w);
                add(u, v, -w);
            }
        }
        return detail::det(a);
    }
    // 返回从start到end使用每条有向边恰一次的序列数（首边未固定）。
    Z eulerTrails(int n, const std::vector<std::pair<int, int>> &arcs, int start, int end) {
        assert(n >= 1 && start >= 0 && start < n && end >= 0 && end < n && arcs.size() < P);
        if (arcs.empty())
            return start == end ? Z(1) : Z(0);
        std::vector<int> in(n), out(n);
        for (auto [u, v] : arcs) {
            assert(u >= 0 && u < n && v >= 0 && v < n);
            ++out[u];
            ++in[v];
        }
        for (int u = 0; u < n; ++u)
            if (out[u] - in[u] != (u == start) - (u == end))
                return 0;
        if (!out[start])
            return 0;
        std::vector<int> id(n, -1);
        int k = 0;
        for (int u = 0; u < n; ++u)
            if (in[u] || out[u])
                id[u] = k++;
        std::vector<std::tuple<int, int, Z>> e;
        for (auto [u, v] : arcs)
            e.emplace_back(id[u], id[v], 1);
        Z ans = weighted(k, e, id[end], 2);
        std::vector<Z> fact(arcs.size() + 1, 1);
        for (int i = 1; i < (int)fact.size(); ++i)
            fact[i] = fact[i - 1] * i;
        for (int u = 0; u < n; ++u)
            if (id[u] >= 0) {
                int d = out[u] - 1 + (u == end);
                if (d < 0)
                    return 0;
                ans *= fact[d];
            }
        return ans;
    }
}

