#ifndef XCPC_WEIGHTED_BLOSSOM_HPP
#define XCPC_WEIGHTED_BLOSSOM_HPP
namespace xcpc_weighted_blossom {
    // 一般图最大权匹配
    class WeightedBlossom {
        using Wide = __int128;
        struct edge {
            int u = 0, v = 0;
            i64 w = 0;
        };
        int n, n_x, stamp = 0;
        bool solved = false;
        std::vector<std::vector<edge>> g;
        std::vector<Wide> lab;
        std::vector<int> match, slack, st, pa, S, vis;
        std::vector<std::vector<int>> flo_from, flo;
        std::queue<int> q;

        // 交错森林中 S=0 为外点（偶层），S=1 为内点（奇层），S=-1 为未访问。
        // 缩花后的边保留原端点 u/v；flo_from 记录原点所属的花瓣，供展开与重配使用。
        Wide e_delta(const edge &e) {
            return lab[e.u] + lab[e.v] - Wide(e.w) * 2;
        }
        void update_slack(int u, int x) {
            if (!slack[x] || e_delta(g[u][x]) < e_delta(g[slack[x]][x])) {
                slack[x] = u;
            }
        }
        void set_slack(int x) {
            slack[x] = 0;
            for (int u = 1; u <= n; ++u) {
                if (g[u][x].w > 0 && st[u] != x && S[st[u]] == 0) {
                    update_slack(u, x);
                }
            }
        }
        void q_push(int x) {
            if (x <= n) {
                q.push(x);
            } else {
                for (int i = 0; i < flo[x].size(); i++) {
                    q_push(flo[x][i]);
                }
            }
        }
        void set_st(int x, int b) {
            st[x] = b;
            if (x > n) {
                for (int i = 0; i < flo[x].size(); ++i) {
                    set_st(flo[x][i], b);
                }
            }
        }
        int get_pr(int b, int xr) {
            int pr = std::find(flo[b].begin(), flo[b].end(), xr) - flo[b].begin();
            if (pr % 2 == 1) {
                std::reverse(flo[b].begin() + 1, flo[b].end());
                return (int)flo[b].size() - pr;
            }
            return pr;
        }
        void set_match(int u, int v) {
            match[u] = g[u][v].v;
            if (u <= n)
                return;
            edge e = g[u][v];
            int xr = flo_from[u][e.u], pr = get_pr(u, xr);
            for (int i = 0; i < pr; ++i) {
                set_match(flo[u][i], flo[u][i ^ 1]);
            }
            set_match(xr, v);
            std::rotate(flo[u].begin(), flo[u].begin() + pr, flo[u].end());
        }
        void augment(int u, int v) {
            while (1) {
                int xnv = st[match[u]];
                set_match(u, v);
                if (!xnv)
                    return;
                set_match(xnv, st[pa[xnv]]);
                u = st[pa[xnv]], v = xnv;
            }
        }
        int get_lca(int u, int v) {
            // 每次搜索独立标记；0保留为未访问，避免首次搜索把两个自由根误判为同树。
            if (stamp == INT_MAX) {
                std::fill(vis.begin(), vis.end(), 0);
                stamp = 0;
            }
            ++stamp;
            for (; u || v; std::swap(u, v)) {
                if (u == 0)
                    continue;
                if (vis[u] == stamp)
                    return u;
                vis[u] = stamp;
                u = st[match[u]];
                if (u)
                    u = st[pa[u]];
            }
            return 0;
        }
        void add_blossom(int u, int lca, int v) {
            int b = n + 1;
            while (b <= n_x && st[b])
                ++b;
            if (b > n_x)
                ++n_x;
            lab[b] = 0, S[b] = 0;
            match[b] = match[lca];
            flo[b].clear();
            flo[b].push_back(lca);
            for (int x = u, y; x != lca; x = st[pa[y]]) {
                flo[b].push_back(x);
                flo[b].push_back(y = st[match[x]]);
                q_push(y);
            }
            std::reverse(flo[b].begin() + 1, flo[b].end());
            for (int x = v, y; x != lca; x = st[pa[y]]) {
                flo[b].push_back(x);
                flo[b].push_back(y = st[match[x]]);
                q_push(y);
            }
            set_st(b, b);
            for (int x = 1; x <= n_x; ++x) {
                g[b][x].w = g[x][b].w = 0;
            }
            for (int x = 1; x <= n; ++x) {
                flo_from[b][x] = 0;
            }
            for (int i = 0; i < flo[b].size(); ++i) {
                int xs = flo[b][i];
                for (int x = 1; x <= n_x; ++x) {
                    if (g[b][x].w == 0 || e_delta(g[xs][x]) < e_delta(g[b][x])) {
                        g[b][x] = g[xs][x], g[x][b] = g[x][xs];
                    }
                }
                for (int x = 1; x <= n; ++x) {
                    if (flo_from[xs][x]) {
                        flo_from[b][x] = xs;
                    }
                }
            }
            set_slack(b);
        }
        void expand_blossom(int b) {
            for (int i = 0; i < flo[b].size(); ++i) {
                set_st(flo[b][i], flo[b][i]);
            }
            int xr = flo_from[b][g[b][pa[b]].u], pr = get_pr(b, xr);
            for (int i = 0; i < pr; i += 2) {
                int xs = flo[b][i], xns = flo[b][i + 1];
                pa[xs] = g[xns][xs].u;
                S[xs] = 1, S[xns] = 0;
                slack[xs] = 0, set_slack(xns);
                q_push(xns);
            }
            S[xr] = 1, pa[xr] = pa[b];
            for (int i = pr + 1; i < flo[b].size(); ++i) {
                int xs = flo[b][i];
                S[xs] = -1, set_slack(xs);
            }
            st[b] = 0;
        }
        bool on_found_edge(const edge &e) {
            int u = st[e.u], v = st[e.v];
            if (S[v] == -1) {
                pa[v] = e.u, S[v] = 1;
                int nu = st[match[v]];
                slack[v] = slack[nu] = 0;
                S[nu] = 0, q_push(nu);
            } else if (S[v] == 0) {
                int lca = get_lca(u, v);
                if (!lca) {
                    return augment(u, v), augment(v, u), true;
                } else {
                    add_blossom(u, lca, v);
                }
            }
            return false;
        }
        bool bfs() {
            std::fill(S.begin() + 1, S.begin() + n_x + 1, -1);
            std::fill(slack.begin() + 1, slack.begin() + n_x + 1, 0);
            q = std::queue<int>();
            for (int x = 1; x <= n_x; ++x) {
                if (st[x] == x && !match[x]) {
                    pa[x] = S[x] = 0;
                    q_push(x);
                }
            }
            if (q.empty())
                return false;
            while (1) {
                while (q.size()) {
                    int u = q.front();
                    q.pop();
                    if (S[st[u]] == 1)
                        continue;
                    for (int v = 1; v <= n; ++v) {
                        if (g[u][v].w > 0 && st[u] != st[v]) {
                            if (e_delta(g[u][v]) == 0) {
                                if (on_found_edge(g[u][v]))
                                    return true;
                            } else {
                                update_slack(u, st[v]);
                            }
                        }
                    }
                }
                Wide d = Wide(1) << 120;
                for (int b = n + 1; b <= n_x; ++b) {
                    if (st[b] == b && S[b] == 1) {
                        d = std::min(d, lab[b] / 2);
                    }
                }
                for (int x = 1; x <= n_x; ++x) {
                    if (st[x] == x && slack[x]) {
                        if (S[x] == -1) {
                            d = std::min(d, e_delta(g[slack[x]][x]));
                        } else if (S[x] == 0) {
                            d = std::min(d, e_delta(g[slack[x]][x]) / 2);
                        }
                    }
                }
                for (int u = 1; u <= n; ++u) {
                    if (S[st[u]] == 0) {
                        if (lab[u] <= d)
                            return 0;
                        lab[u] -= d;
                    } else if (S[st[u]] == 1) {
                        lab[u] += d;
                    }
                }
                for (int b = n + 1; b <= n_x; ++b) {
                    if (st[b] == b) {
                        if (S[st[b]] == 0) {
                            lab[b] += d * 2;
                        } else if (S[st[b]] == 1) {
                            lab[b] -= d * 2;
                        }
                    }
                }
                q = std::queue<int>();
                for (int x = 1; x <= n_x; ++x) {
                    if (st[x] == x && slack[x] && st[slack[x]] != x &&
                        e_delta(g[slack[x]][x]) == 0) {
                        if (on_found_edge(g[slack[x]][x]))
                            return true;
                    }
                }
                for (int b = n + 1; b <= n_x; ++b) {
                    if (st[b] == b && S[b] == 1 && lab[b] == 0) {
                        expand_blossom(b);
                    }
                }
            }
            return false;
        }

      public:
        // 创建 n 个点（编号 1..n）；n=0 允许，无返回值；负数或容量编号溢出抛异常。
        explicit WeightedBlossom(int n) : n(n), n_x(n) {
            if (n < 0 || n > (INT_MAX - 1) / 2)
                throw std::invalid_argument("invalid vertex count");
            int size = 2 * n + 1;
            g.assign(size, std::vector<edge>(size));
            lab.resize(size);
            match = slack = st = pa = S = vis = std::vector<int>(size);
            flo_from.assign(size, std::vector<int>(size));
            flo.resize(size);
            for (int u = 1; u <= n; ++u)
                for (int v = 1; v <= n; ++v)
                    g[u][v] = {u, v, 0};
        }

        // 加一条无向边，重边取最大权，忽略自环与非正权；无返回值，越界抛异常。
        void addEdge(int u, int v, i64 w) {
            if (u < 1 || u > n || v < 1 || v > n)
                throw std::out_of_range("vertex outside 1..n");
            if (u == v || w <= 0)
                return;
            g[u][v].w = g[v][u].w = std::max(g[u][v].w, w);
            solved = false;
        }

        // 从空匹配求最大权匹配，返回 {权重和, 匹配边数}；权重和超出 i64 时抛异常。
        std::pair<i64, int> solve() {
            solved = false;
            std::fill(match.begin(), match.end(), 0);
            std::fill(st.begin(), st.end(), 0);
            std::fill(vis.begin(), vis.end(), 0);
            n_x = n;
            stamp = 0;
            i64 w_max = 0;
            for (int u = 0; u <= n; ++u) {
                st[u] = u;
                flo[u].clear();
            }
            for (int u = 1; u <= n; ++u) {
                for (int v = 1; v <= n; ++v) {
                    flo_from[u][v] = u == v ? u : 0;
                    w_max = std::max(w_max, g[u][v].w);
                }
            }
            std::fill(lab.begin() + 1, lab.begin() + n + 1, Wide(w_max));
            int count = 0;
            while (bfs())
                ++count;
            Wide total = 0;
            for (int u = 1; u <= n; ++u)
                if (match[u] && match[u] < u)
                    total += g[u][match[u]].w;
            if (total > std::numeric_limits<i64>::max())
                throw std::overflow_error("matching weight exceeds i64");
            solved = true;
            return {i64(total), count};
        }

        // 返回点 u 的匹配点（0 表示未匹配）；越界或尚未 solve 时抛异常。
        int mate(int u) const {
            if (u < 1 || u > n)
                throw std::out_of_range("vertex outside 1..n");
