    struct Edge {
        int from;
        int to;
        T cap;
        T flow;
    };

    // 按加边顺序返回原始边及流量
    std::vector<Edge> edges() {
        std::vector<Edge> a;
        for (int i = 0; i < e.size(); i += 2) {
