        return t.size() - 1;
    }

    // 从当前末尾状态 p 追加字符编号 c（0..25），返回新的末尾状态；每串初始 p=1
    int extend(int p, int c) {
        if (t[p].next[c]) {
            int q = t[p].next[c];
            if (t[q].len == t[p].len + 1) {
                return q;
            }
            int r = newNode();
            t[r].len = t[p].len + 1;
            t[r].link = t[q].link;
            t[r].next = t[q].next;
            t[q].link = r;
            while (t[p].next[c] == q) {
                t[p].next[c] = r;
                p = t[p].link;
            }
            return r;
        }
        int cur = newNode();
        t[cur].len = t[p].len + 1;
        while (!t[p].next[c]) {
            t[p].next[c] = cur;
            p = t[p].link;
        }
        t[cur].link = extend(p, c);
        return cur;
    }

    // 从当前末尾状态 p 追加小写字符 c，返回新的末尾状态；每串初始 p=1。
    int extend(int p, char c, char offset = 'a') {
        return extend(p, c - offset);
    }

    // 返回整数转移目标。
    int next(int p, int x) {
        return t[p].next[x];
    }

    // 返回字符转移目标。
    int next(int p, char c, char offset = 'a') {
        return next(p, c - offset);
    }

    // 返回后缀链接。
    int link(int p) {
        return t[p].link;
    }

    // 返回状态最大串长。
    int len(int p) {
        return t[p].len;
    }

    // 返回状态总数。
    int size() {
        return t.size();
    }
};

