int minimalRotation(const std::string &s) {
    int n = s.size();
    int i = 0, j = 1, k = 0;
    while (i < n && j < n && k < n) {
        unsigned char a = s[(i + k) % n], b = s[(j + k) % n];
        if (a == b) {
            k++;
        } else if (a < b) {
            j = j + k + 1;
            if (j == i) {
                j++;
            }
            k = 0;
        } else {
            i = i + k + 1;
            if (i == j) {
                i++;
            }
            k = 0;
        }
    }
    return std::min(i, j);
}

