#ifndef XCPC_MODPOW
#define XCPC_MODPOW

// 返回 a*b mod p，结果规范到 [0,p)。
i64 mulMod(i64 a, i64 b, i64 p) {
    i64 r = i64(i128(a) * b % p);
    return r < 0 ? r + p : r;
}

// 返回 a^b mod p。
i64 power(i64 a, i64 b, i64 p) {
    if (p == 1) {
        return 0;
    }
    i64 res = 1 % p;
    for (; b; b >>= 1, a = mulMod(a, a, p)) {
        if (b & 1) {
            res = mulMod(res, a, p);
        }
    }
    return res;
}

#endif // XCPC_MODPOW

