template <> int MInt<0>::Mod = 1000000007;

template <int V, int P> constexpr MInt<P> CInv = MInt<P>(V).inv();

// 库级默认模数。
#ifndef XCPC_MODINT_P
#define XCPC_MODINT_P
constexpr int P = 1000000007;
#endif
using Z = MInt<P>;

#endif // XCPC_MODINT

// 模素数下的阶乘、逆阶乘与组合数查询。
struct Comb {
    int n;
    std::vector<Z> _fac;
    std::vector<Z> _invfac;
    std::vector<Z> _inv;

    // 构造只含 0! 的空表。
    Comb() : n{0}, _fac{1}, _invfac{1}, _inv{0} {}
    // 构造并预处理到 n。
    Comb(int n) : Comb() {
        init(n);
    }

    // 扩容预处理到 m，已覆盖时不缩小。
    void init(int m) {
        if (m <= n) {
            return;
        }
        _fac.resize(m + 1);
        _invfac.resize(m + 1);
        _inv.resize(m + 1);
        for (int i = n + 1; i <= m; i++) {
            _fac[i] = _fac[i - 1] * i;
        }
        _invfac[m] = _fac[m].inv();
        for (int i = m; i > n; i--) {
            _invfac[i - 1] = _invfac[i] * i;
            _inv[i] = _invfac[i] * _fac[i - 1];
        }
