// 类型无关的 gcd：std::gcd 对 __int128 编译不过，故自行实现辗转相除
template <class T> T gcdAbs(T a, T b) {
    if (a < 0)
        a = -a;
    if (b < 0)
        b = -b;
    while (b != 0) {
        T t = a % b;
        a = b;
        b = t;
    }
    return a;
}

// 精确有理数：分子 num、分母 den，恒为最简且 den>0
template <class T> struct Frac {
    T num;
    T den;

    // 默认构造为 0/1
    Frac() : Frac(0, 1) {}
    // 单参构造为整数分数 num_/1
    Frac(T num_) : Frac(num_, 1) {}
    // 构造并约分；den_ 不能为 0，自动令分母为正
    Frac(T num_, T den_) : num(num_), den(den_) {
        if (den < 0) {
            den = -den;
            num = -num;
        }
        T g = gcdAbs(num, den);
        num /= g;
        den /= g;
    }

    // 返回浮点近似值，可能损失精度
    explicit operator double() const {
        return 1. * num / den;
    }

    // 原地加法，返回 *this
    Frac &operator+=(const Frac &rhs) {
        num = num * rhs.den + rhs.num * den;
        den *= rhs.den;
        T g = gcdAbs(num, den);
        num /= g;
        den /= g;
        return *this;
    }
    // 原地减法，返回 *this
    Frac &operator-=(const Frac &rhs) {
        num = num * rhs.den - rhs.num * den;
        den *= rhs.den;
        T g = gcdAbs(num, den);
        num /= g;
        den /= g;
        return *this;
    }
    // 原地乘法，返回 *this
    Frac &operator*=(const Frac &rhs) {
        num *= rhs.num;
        den *= rhs.den;
        T g = gcdAbs(num, den);
        num /= g;
        den /= g;
        return *this;
    }
    // 原地除法；rhs 不能为 0，返回 *this
    Frac &operator/=(const Frac &rhs) {
        T divisor = rhs.num; // rhs 可能就是 *this，先保存尚未修改的分子
        num *= rhs.den;
        den *= divisor;
        if (den < 0) {
            num = -num;
            den = -den;
        }
        T g = gcdAbs(num, den);
        num /= g;
        den /= g;
        return *this;
    }

    // 返回两分数之和
    friend Frac operator+(Frac lhs, const Frac &rhs) {
        return lhs += rhs;
    }
    // 返回两分数之差
    friend Frac operator-(Frac lhs, const Frac &rhs) {
        return lhs -= rhs;
    }
    // 返回两分数之积
    friend Frac operator*(Frac lhs, const Frac &rhs) {
        return lhs *= rhs;
    }
    // 返回两分数之商；rhs 不能为 0
    friend Frac operator/(Frac lhs, const Frac &rhs) {
        return lhs /= rhs;
    }
    // 返回相反数
    friend Frac operator-(const Frac &a) {
        return Frac(-a.num, a.den);
    }
    // 相等比较（交叉乘法，须保证不溢出）
    friend bool operator==(const Frac &lhs, const Frac &rhs) {
        return lhs.num * rhs.den == rhs.num * lhs.den;
    }
    // 不等比较
    friend bool operator!=(const Frac &lhs, const Frac &rhs) {
        return lhs.num * rhs.den != rhs.num * lhs.den;
    }
    // 小于比较
    friend bool operator<(const Frac &lhs, const Frac &rhs) {
        return lhs.num * rhs.den < rhs.num * lhs.den;
    }
    // 大于比较
    friend bool operator>(const Frac &lhs, const Frac &rhs) {
        return lhs.num * rhs.den > rhs.num * lhs.den;
    }
    // 小于等于比较
    friend bool operator<=(const Frac &lhs, const Frac &rhs) {
        return lhs.num * rhs.den <= rhs.num * lhs.den;
    }
    // 大于等于比较
    friend bool operator>=(const Frac &lhs, const Frac &rhs) {
        return lhs.num * rhs.den >= rhs.num * lhs.den;
    }
    // 输出为 分子/分母
    friend std::ostream &operator<<(std::ostream &os, Frac x) {
        return os << x.num << "/" << x.den;
    }
};

