        for (int i = 0; x; i++) {
            a[i] = x % 10;
            x /= 10;
        }
    }

    // 乘非负 int；结果须小于 10^N
    BigInt &operator*=(int x) {
        for (int i = 0; i < N; i++) {
            a[i] *= x;
