            powers[i] = v;
            x[i] = a[v];
            y[i] = b[v];
            v = v * primitive % prime;
        }
        assert(v == 1);
        auto c = cyclic(x, y, prime - 1);
        V h(prime);
        for (int i = 0; i < prime - 1; ++i)
