            return polyPow(f, bounded, m); // 能留下非零项时，bounded就是未缩减的真指数。
        i64 reduced = modP + i64(MOD) * ((modPhi - modP + MOD - 1) % (MOD - 1));
        return polyPow(f, reduced, m); // P与P-1互素；m<P时相同两种余数给出相同截断幂。
    }
#endif // XCPC_POLY_STRING_POWER
} // namespace poly

