        if (m == 1) {
            return {0};
        }
        auto g = polyDerivative(f);
        auto inv = polyInv(f, m);
        auto h = nttMul(g, inv);
        h.resize(m - 1, 0);
        auto res = polyIntegral(h);
        res.resize(m, 0);
        return res;
    }

    // 返回 exp(f) 的前 m 项，result[i] 是 x^i 系数；要求 f 非空且 f[0]=0
    std::vector<int> polyExp(const std::vector<int> &f, int m) {
        assert(!f.empty() && f[0] == 0 && "polyExp 要求 f[0] == 0");
        if (m <= 0) {
            return {};
        }
        std::vector<int> g(1, 1);
        for (int cur = 1; cur < m; cur <<= 1) {
            int nxt = min(2 * cur, m);
            auto lg = polyLn(g, nxt);
            std::vector<int> t(nxt, 0);
            for (int i = 0; i < nxt && i < int(f.size()); i++) {
                t[i] = f[i];
            }
            t[0] = (t[0] + 1) % MOD;
            for (int i = 0; i < nxt; i++) {
                t[i] = (t[i] - lg[i] + MOD) % MOD;
            }
            auto ng = nttMul(g, t);
            ng.resize(nxt, 0);
            g = ng;
        }
        g.resize(m, 0);
        return g;
    }

    // 返回乘积系数，result[i] 是 x^i 系数；任一输入为空返回空
    std::vector<int> polyMul(const std::vector<int> &a, const std::vector<int> &b) {
        return nttMul(a, b);
    }

    // 返回 {q, r} 使 f = qg + r 且 deg r < deg g；deg f < deg g 时 q = {0}
    std::pair<std::vector<int>, std::vector<int>> polyDivMod(std::vector<int> f,
                                                             std::vector<int> g) {
        auto trim = [](std::vector<int> &a) {
            while (!a.empty() && a.back() == 0) {
                a.pop_back();
            }
            if (a.empty()) {
                a = {0};
            }
        };
        trim(f);
        trim(g);
        int df = int(f.size()) - 1, dg = int(g.size()) - 1;
        if (g == std::vector<int>{0}) {
            return {{0}, f}; // 除数为零多项式，退化为返回 f
        }
        if (df < dg) {
            return {{0}, f};
        }
        auto rev = [](const std::vector<int> &a) {
            std::vector<int> r = a;
            std::reverse(r.begin(), r.end());
            return r;
        };
        int k = df - dg + 1;
        auto invg = polyInv(rev(g), k);
        auto q = nttMul(rev(f), invg);
        q.resize(k, 0);
        std::reverse(q.begin(), q.end());
        trim(q);
        auto p = nttMul(q, g);
        std::vector<int> r(f.size(), 0);
        for (int i = 0; i < int(r.size()); i++) {
            r[i] = ((f[i] - (i < int(p.size()) ? p[i] : 0)) % MOD + MOD) % MOD;
        }
        trim(r);
        return {q, r};
    }

    // 返回余式系数，result[i] 是 x^i 系数；有效除法要求 g 非零
    std::vector<int> polyMod(std::vector<int> f, std::vector<int> g) {
        return polyDivMod(std::move(f), std::move(g)).second;
    }

    // 返回 f^k 的前 m 项，result[i] 是 x^i 系数；k 必须非负
    std::vector<int> polyPow(const std::vector<int> &f, i64 k, int m) {
        assert(k >= 0 && "polyPow 要求 k >= 0");
        if (m <= 0)
            return {};
        if (k == 0) {
            std::vector<int> r(m, 0);
            if (m > 0) {
                r[0] = 1;
            }
            return r;
        }
        int shift = 0;
        while (shift < int(f.size()) && f[shift] == 0)
            ++shift;
        if (shift == int(f.size()) || (shift && k > (m - 1) / shift))
            return std::vector<int>(m, 0);
        if (shift) {
            auto tail =
                polyPow(std::vector<int>(f.begin() + shift, f.end()), k, m - int(shift * k));
            tail.insert(tail.begin(), int(shift * k), 0);
            return tail;
        }
        auto normalized = f;
        int inverse = powerMod(f[0], MOD - 2);
        for (auto &value : normalized)
            value = int(1LL * value * inverse % MOD);
        auto g = polyLn(normalized, m);
        std::vector<int> kg(m, 0);
        for (int i = 0; i < m; i++) {
            kg[i] = int(1LL * g[i] * (k % MOD) % MOD);
        }
        auto result = polyExp(kg, m);
        int factor = powerMod(f[0], k);
        for (auto &value : result)
            value = int(1LL * value * factor % MOD);
        return result;
    }

#endif // XCPC_POLY_EXTENSIONS
} // namespace poly

namespace interpolation {
    using V = std::vector<int>;
    constexpr int mod = poly::MOD;
    // 返回等差步长为 1 的节点上的单点插值；支持负 x 和 start
    int consecutive(const V &y, long long x, long long start = 0) {
        int n = y.size();
        assert(n > 0 && n < mod);
        x %= mod;
        start %= mod;
        x = (x - start) % mod;
        if (x < 0)
            x += mod;
        if (x < n)
            return y[x];
        V pre(n + 1, 1), suf(n + 1, 1), fac(n, 1), inv(n, 1);
        for (int i = 0; i < n; ++i)
            pre[i + 1] = 1LL * pre[i] * (x - i + mod) % mod;
        for (int i = n - 1; i >= 0; --i)
            suf[i] = 1LL * suf[i + 1] * (x - i + mod) % mod;
        for (int i = 1; i < n; ++i)
            fac[i] = 1LL * fac[i - 1] * i % mod;
        inv[n - 1] = poly::powerMod(fac[n - 1], mod - 2);
        for (int i = n - 1; i > 0; --i)
            inv[i - 1] = 1LL * inv[i] * i % mod;
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            long long v =
                1LL * y[i] * pre[i] % mod * suf[i + 1] % mod * inv[i] % mod * inv[n - 1 - i] % mod;
            ans = (ans + ((n - 1 - i) & 1 ? -v : v) + mod) % mod;
        }
        return ans;
    }
    // 维护节点乘积树，支持批量求值与插值
    struct ProductTree {
      private:
        int n;
        V x;
        std::vector<V> t;
        void build(int v, int l, int r) {
            if (r - l == 1) {
                t[v] = {(mod - x[l]) % mod, 1};
                return;
            }
            int m = (l + r) / 2;
            build(v * 2, l, m);
            build(v * 2 + 1, m, r);
            t[v] = poly::nttMul(t[v * 2], t[v * 2 + 1]);
        }
        void eval(int v, int l, int r, const V &f, V &ans) const {
            auto rem = poly::polyMod(f, t[v]);
            if (r - l == 1) {
                ans[l] = rem[0];
                return;
            }
            int m = (l + r) / 2;
            eval(v * 2, l, m, rem, ans);
            eval(v * 2 + 1, m, r, rem, ans);
        }
        V interp(int v, int l, int r, const V &w) const {
            if (r - l == 1)
                return {w[l]};
            int m = (l + r) / 2;
            auto a = poly::nttMul(interp(v * 2, l, m, w), t[v * 2 + 1]),
                 b = poly::nttMul(interp(v * 2 + 1, m, r, w), t[v * 2]);
            a.resize(r - l);
            for (int i = 0; i < (int)b.size(); ++i)
                a[i] = (a[i] + b[i]) % mod;
            return a;
        }

      public:
        // 构造节点乘积树；求值允许重复节点，插值要求节点互异
        explicit ProductTree(V xs) : n(xs.size()), x(std::move(xs)), t(std::max(1, 4 * n)) {
            assert(n < mod);
            for (auto &v : x) {
                v %= mod;
                if (v < 0)
                    v += mod;
            }
            if (n)
                build(1, 0, n);
        }
        // 返回 result[i]=f(x[i])，保持节点顺序；空节点返回空
        V evaluate(const V &f) const {
            V ans(n);
            if (n)
                eval(1, 0, n, f, ans);
            return ans;
        }
        // 返回长度 n 的插值系数，result[i] 对应 x^i；要求节点互异
        V interpolate(const V &y) const {
            assert(y.size() == x.size());
            if (!n)
                return {};
            auto d = evaluate(poly::polyDerivative(t[1]));
            V w(n);
            for (int i = 0; i < n; ++i) {
                assert(d[i] != 0);
                w[i] = 1LL * y[i] * poly::powerMod(d[i], mod - 2) % mod;
            }
            return interp(1, 0, n, w);
        }
    };
}

