        for (int i = 1; i < n; ++i)
            fac[i] = 1LL * fac[i - 1] * i % mod;
        inv[n - 1] = poly::powerMod(fac[n - 1], mod - 2);
        for (int i = n - 1; i > 0; --i)
            inv[i - 1] = 1LL * inv[i] * i % mod;
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            long long v =
                1LL * y[i] * pre[i] % mod * suf[i + 1] % mod * inv[i] % mod * inv[n - 1 - i] % mod;
            ans = (ans + ((n - 1 - i) & 1 ? -v : v) + mod) % mod;
        }
        return ans;
    }
    // 维护节点乘积树，支持批量求值与插值
    struct ProductTree {
      private:
        int n;
        V x;
        std::vector<V> t;
        void build(int v, int l, int r) {
            if (r - l == 1) {
                t[v] = {(mod - x[l]) % mod, 1};
                return;
            }
            int m = (l + r) / 2;
            build(v * 2, l, m);
            build(v * 2 + 1, m, r);
            t[v] = poly::nttMul(t[v * 2], t[v * 2 + 1]);
        }
        void eval(int v, int l, int r, const V &f, V &ans) const {
            auto rem = poly::polyMod(f, t[v]);
            if (r - l == 1) {
                ans[l] = rem[0];
                return;
            }
            int m = (l + r) / 2;
            eval(v * 2, l, m, rem, ans);
