        }

      public:
        // 构造节点乘积树；求值允许重复节点，插值要求节点互异
        explicit ProductTree(V xs) : n(xs.size()), x(std::move(xs)), t(std::max(1, 4 * n)) {
            assert(n < mod);
            for (auto &v : x) {
                v %= mod;
                if (v < 0)
                    v += mod;
            }
            if (n)
                build(1, 0, n);
        }
        // 返回 result[i]=f(x[i])，保持节点顺序；空节点返回空
        V evaluate(const V &f) const {
            V ans(n);
            if (n)
                eval(1, 0, n, f, ans);
            return ans;
        }
        // 返回长度 n 的插值系数，result[i] 对应 x^i；要求节点互异
        V interpolate(const V &y) const {
            assert(y.size() == x.size());
            if (!n)
                return {};
            auto d = evaluate(poly::polyDerivative(t[1]));
            V w(n);
            for (int i = 0; i < n; ++i) {
                assert(d[i] != 0);
                w[i] = 1LL * y[i] * poly::powerMod(d[i], mod - 2) % mod;
            }
            return interp(1, 0, n, w);
        }
    };
}

