namespace GeoTriangle {
    using Real = long double;
    using P = Point<Real>;
    struct Centers {
        P circum, in, orth;
        std::array<P, 3> ex; // ex[0/1/2] 分别为顶点 a/b/c 所对边的旁心
        Real inRadius, circumRadius;
    };
    // 传入三个点；返回重心，允许重复点与共线。
    P centroid(P a, P b, P c) {
        return a + ((b - a) + (c - a)) / Real(3);
    }
    // 按 a,b,c 的顺序求各心；|叉积|<=eps 返回空，不产生无穷坐标。
    std::optional<Centers> centers(P a, P b, P c, Real eps = 1e-12L) {
        P u = b - a, v = c - a;
        Real d = cross(u, v);
        if (std::abs(d) <= eps)
            return std::nullopt;
        Real A = std::sqrt(square(b - c)), B = std::sqrt(square(c - a)),
             C = std::sqrt(square(a - b));
        Real s = A + B + C;
        P offset{(square(u) * v.y - square(v) * u.y) / (2 * d),
                 (u.x * square(v) - v.x * square(u)) / (2 * d)};
        P o = a + offset, in = a + (u * B + v * C) / s;
        return Centers{o,
                       in,
                       a + u + v - offset * Real(2),
                       {a + (u * B + v * C) / (-A + B + C), a + (-u * B + v * C) / (A - B + C),
                        a + (u * B - v * C) / (A + B - C)},
                       std::abs(d) / s,
                       std::sqrt(square(offset))};
    }
}

