// 返回去重后逆时针凸包，不重复首点；共线只留两端，空输入为空。
std::vector<Point<T>> convexHull(std::vector<Point<T>> p) {
    std::sort(p.begin(), p.end());
    p.erase(std::unique(p.begin(), p.end()), p.end());
    int n = p.size();
    if (n <= 2) {
        return p;
    }
    std::vector<Point<T>> h(2 * n);
    int k = 0;
    for (int i = 0; i < n; i++) {
        while (k >= 2 && cross(h[k - 1] - h[k - 2], p[i] - h[k - 1]) <= 0) {
            k--;
        }
        h[k++] = p[i];
    }
    for (int i = n - 2, t = k + 1; i >= 0; i--) {
        while (k >= t && cross(h[k - 1] - h[k - 2], p[i] - h[k - 1]) <= 0) {
            k--;
        }
        h[k++] = p[i];
    }
    h.resize(k - 1);
