    int n = h.size();
    if (n == 1) {
        return 0;
    }
    if (n == 2) {
        return std::sqrt(square(h[1] - h[0]));
    }
    double ans = 0;
    int j = 1;
    for (int i = 0; i < n; i++) {
        while (cross(h[(i + 1) % n] - h[i], h[(j + 1) % n] - h[i]) >
               cross(h[(i + 1) % n] - h[i], h[j] - h[i])) {
            j = (j + 1) % n;
        }
        ans = std::max(ans, std::sqrt(square(h[j] - h[i])));
        ans = std::max(ans, std::sqrt(square(h[j] - h[(i + 1) % n])));
    }
    return ans;
}

