namespace Minkowski {
    using P = Point<long long>;
    using Int = __int128;
    namespace detail {
        Int det(P a, P b) {
            return Int(a.x) * b.y - Int(a.y) * b.x;
        }
        Int turn(P a, P b, P c) {
            return det(b - a, c - a);
        }
        std::vector<P> hull(std::vector<P> p) {
            std::sort(p.begin(), p.end());
            p.erase(std::unique(p.begin(), p.end()), p.end());
            if (p.size() < 2)
                return p;
            std::vector<P> h;
            for (P a : p) {
                while (h.size() > 1 && turn(h[h.size() - 2], h.back(), a) <= 0)
                    h.pop_back();
                h.push_back(a);
            }
            int k = int(h.size());
            for (int i = int(p.size()) - 2; i >= 0; --i) {
                while (int(h.size()) > k && turn(h[h.size() - 2], h.back(), p[i]) <= 0)
                    h.pop_back();
                h.push_back(p[i]);
            }
            h.pop_back();
            return h;
        }
        void rotate(std::vector<P> &p) {
            if (!p.empty())
                std::rotate(p.begin(),
                            std::min_element(
                                p.begin(), p.end(),
                                [](P a, P b) { return std::tie(a.y, a.x) < std::tie(b.y, b.x); }),
                            p.end());
        }
        void valid(const std::vector<P> &p) {
            for (P a : p)
                if (a.x < -1000000000LL || a.x > 1000000000LL || a.y < -1000000000LL ||
                    a.y > 1000000000LL)
                    throw std::invalid_argument("Minkowski: coordinate exceeds 1e9");
            if (p.size() > 2)
                for (int i = 0; i < int(p.size()); ++i)
                    if (turn(p[i], p[(i + 1) % p.size()], p[(i + 2) % p.size()]) <= 0)
                        throw std::invalid_argument("Minkowski: input not strict CCW convex");
        }
        int half(P a) {
            return a.y < 0 || (a.y == 0 && a.x < 0);
        }
        bool less(P a, P b) {
            return half(a) != half(b) ? half(a) < half(b) : det(a, b) > 0;
        }
    }
    // 两闭凸集求向量和；空输入返回空，点/段按定义求和，非法方向/坐标抛异常。
    std::vector<P> sum(std::vector<P> a, std::vector<P> b) {
        detail::valid(a);
        detail::valid(b);
        if (a.empty() || b.empty())
            return {};
        if (a.size() < 3 || b.size() < 3) {
            std::vector<P> all;
            for (P x : a)
                for (P y : b)
                    all.push_back(x + y);
            auto h = detail::hull(all);
            detail::rotate(h);
            return h;
        }
        detail::rotate(a);
        detail::rotate(b);
        int n = int(a.size()), m = int(b.size()), i = 0, j = 0;
        std::vector<P> h{a[0] + b[0]};
        while (i < n || j < m) {
            P d;
            if (i == n) {
                d = b[(j + 1) % m] - b[j];
                ++j;
            } else if (j == m) {
                d = a[(i + 1) % n] - a[i];
                ++i;
            } else {
                P u = a[(i + 1) % n] - a[i], v = b[(j + 1) % m] - b[j];
                if (detail::less(u, v)) {
                    d = u;
                    ++i;
                } else if (detail::less(v, u)) {
                    d = v;
                    ++j;
                } else {
                    d = u + v;
                    ++i;
                    ++j;
                }
            }
            h.push_back(h.back() + d);
        }
        h.pop_back();
        return h;
    }
}

