// 返回点集最近点对的距离平方；少于 2 点返回 -1，重复点返回 0。
i64 closestPairSquared(std::vector<Point<i64>> pts) {
    int n = pts.size();
    if (n < 2) {
        return -1;
    }
    std::sort(pts.begin(), pts.end(), [](const Point<i64> &a, const Point<i64> &b) {
        return a.x == b.x ? a.y < b.y : a.x < b.x;
    });
    i64 ans = std::numeric_limits<i64>::max();
    std::vector<Point<i64>> tmp(n);
    // 不变式：进入 solve(l, r) 时 pts[l..r) 按 x 排好序；返回时 pts[l..r) 按 y 排好序。
    std::function<void(int, int)> solve = [&](int l, int r) {
        if (r - l <= 1) {
            return;
        }
        int mid = (l + r) / 2;
        i64 midx = pts[mid].x;
        solve(l, mid);
        solve(mid, r);
        // 先按 y 归并，pts[l..r) 变成 y 有序（归并必须在取带内点之前做）
        {
            int i = l, j = mid, k = l;
            while (i < mid || j < r) {
                if (j == r || (i < mid && pts[i].y <= pts[j].y)) {
                    tmp[k++] = pts[i++];
                } else {
                    tmp[k++] = pts[j++];
                }
            }
            for (int t = l; t < r; t++) {
                pts[t] = tmp[t];
            }
        }
        // 取带内点：到分界线水平距离平方小于当前 ans；y 有序后逐个向下扫
        std::vector<Point<i64>> strip;
        for (int t = l; t < r; t++) {
            i64 dx = pts[t].x - midx;
            if (dx * dx < ans) {
                strip.push_back(pts[t]);
            }
        }
        for (int k = 0; k < (int)strip.size(); k++) {
            for (int k2 = k + 1; k2 < (int)strip.size(); k2++) {
                i64 dy = strip[k2].y - strip[k].y;
                if (dy * dy >= ans) {
                    break;
                }
                i64 dx = strip[k].x - strip[k2].x;
                ans = std::min(ans, dx * dx + dy * dy);
            }
        }
    };
    solve(0, n);
    return ans;
}

